import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';
class SavedScreen extends ConsumerWidget{const SavedScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider);final saved=c.items('favorites');return Scaffold(appBar:AppBar(title:const Text('Saved')),body:ListView(padding:const EdgeInsets.all(18),children:[const Text('Your saved guides, breeds and reading list stay on this device.'),const SizedBox(height:14),if(saved.isEmpty)const Text('Nothing saved yet. Save an article or breed to find it here.'),...saved.map((e)=>Card(child:ListTile(title:Text(e['title']?.toString()??e['contentId']?.toString()??'Saved item'),subtitle:Text(e['contentType']?.toString()??'Editorial content'),trailing:IconButton(icon:const Icon(Icons.bookmark_remove_outlined),onPressed:()=>c.delete('favorites',e['id'] as String))))),const SizedBox(height:18),const Text('Collections',style:TextStyle(fontWeight:FontWeight.w800,fontSize:19)),...c.items('collections').map((e)=>Card(child:ListTile(title:Text(e['name']?.toString()??'Collection'),subtitle:Text('${(e['contentIds'] as List? ?? []).length} saved items'))))]));}}
